#include "stdlib/stats/base/ndarray/sztest.h"
#include "stdlib/stats/strided/sztest.h"
#include "stdlib/stats/base/ztest/one-sample/results/float32.h"
#include "stdlib/stats/base/ztest/alternatives.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"

/**
* Computes a one-sample Z-test for a one-dimensional single-precision floating-point ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray specifying the alternative hypothesis (as an `int8` value corresponding to `STDLIB_STATS_ZTEST_ALTERNATIVE`).
*     -   a zero-dimensional ndarray specifying the significance level.
*     -   a zero-dimensional ndarray specifying the mean under the null hypothesis.
*     -   a zero-dimensional ndarray specifying the known standard deviation.
*
* -   The test results are written directly into the memory pointed to by `results`, which is not represented as an ndarray, as its layout does not correspond to any ndarray-supported data type.
*
* @param arrays     list containing ndarrays
* @param results    pointer to a results struct into which the test results are written
*/
void stdlib_stats_sztest( const struct ndarray *arrays[], struct stdlib_stats_ztest_one_sample_float32_results *results ) {
	const struct ndarray *x = arrays[ 0 ];
	int8_t alternative;
	float alpha;
	float mu;
	float sigma;

	stdlib_ndarray_get_int8( arrays[ 1 ], NULL, &alternative );
	stdlib_ndarray_get_float32( arrays[ 2 ], NULL, &alpha );
	stdlib_ndarray_get_float32( arrays[ 3 ], NULL, &mu );
	stdlib_ndarray_get_float32( arrays[ 4 ], NULL, &sigma );

	API_SUFFIX(stdlib_strided_sztest_ndarray)( stdlib_ndarray_dimension( x, 0 ), (enum STDLIB_STATS_ZTEST_ALTERNATIVE)alternative, alpha, mu, sigma, (const float *)stdlib_ndarray_data( x ), stdlib_ndarray_stride_elements( x, 0 ), stdlib_ndarray_offset_elements( x ), results );
}
